1	use typst_library::diag::SourceResult;
2	use typst_library::foundations::StyleChain;
3	use typst_library::layout::{
4	    Abs, Axis, Corners, Frame, FrameItem, Point, Rel, Sides, Size,
5	};
6	use typst_library::math::ir::{MathProperties, RadicalItem};
7	use typst_library::math::{EquationElem, MathSize};
8	use typst_library::text::TextElem;
9	use typst_library::visualize::{FixedStroke, Geometry};
10	
11	use super::MathContext;
12	use super::fragment::FrameFragment;
13	use crate::shapes::styled_rect;
14	
15	/// Lays out a [`RadicalItem`].
16	///
17	/// TeXbook page 443, page 360
18	/// See also: <https://www.w3.org/TR/mathml-core/#radicals-msqrt-mroot>
19	#[typst_macros::time(name = "math radical layout", span = props.span)]
20	pub fn layout_radical(
21	    item: &RadicalItem,
22	    ctx: &mut MathContext,
23	    styles: StyleChain,
24	    props: &MathProperties,
25	) -> SourceResult<()> {
26	    let radicand = ctx.layout_into_fragment(&item.radicand, styles)?.into_frame();
27	    let target = {
28	        let sqrt = ctx.layout_into_fragment(&item.sqrt, styles)?;
29	        let styles = item.sqrt.styles().unwrap_or(styles);
30	        let (font, size) = sqrt.font(ctx, styles);
31	        let thickness = font.math().radical_rule_thickness.at(size);
32	        let gap = match styles.get(EquationElem::size) {
33	            MathSize::Display => font.math().radical_display_style_vertical_gap,
34	            _ => font.math().radical_vertical_gap,
35	        }
36	        .at(size);
37	        radicand.height() + thickness + gap
38	    };
39	
40	    // Layout root symbol.
41	    item.sqrt.set_stretch_relative_to(target, Axis::Y);
42	    let sqrt = ctx.layout_into_fragment(&item.sqrt, styles)?;
43	    let sqrt_styles = item.sqrt.styles().unwrap_or(styles);
44	
45	    let (font, size) = sqrt.font(ctx, sqrt_styles);
46	    let thickness = font.math().radical_rule_thickness.at(size);
47	    let extra_ascender = font.math().radical_extra_ascender.at(size);
48	    let kern_before = font.math().radical_kern_before_degree.at(size);
49	    let kern_after = font.math().radical_kern_after_degree.at(size);
50	    let raise_factor = font.math().radical_degree_bottom_raise_percent;
51	    let gap = match sqrt_styles.get(EquationElem::size) {
52	        MathSize::Display => font.math().radical_display_style_vertical_gap,
53	        _ => font.math().radical_vertical_gap,
54	    }
55	    .at(size);
56	
57	    let text_fill = sqrt
58	        .fill()
59	        .unwrap_or_else(|| sqrt_styles.get_ref(TextElem::fill).as_decoration());
60	    let line_width = radicand.width();
61	    let sqrt_stroke = sqrt.stroke();
62	
63	    let sqrt = sqrt.into_frame();
64	
65	    // Layout the index.
66	    let index = item
67	        .index
68	        .as_ref()
69	        .map(|index| ctx.layout_into_fragment(index, styles))
70	        .transpose()?
71	        .map(|frag| frag.into_frame());
72	
73	    // TeXbook, page 443, item 11
74	    // Keep original gap, and then distribute any remaining free space
75	    // equally above and below.
76	    let gap = gap.max((sqrt.height() - thickness - radicand.height() + gap) / 2.0);
77	
78	    let sqrt_ascent = radicand.ascent() + gap + thickness;
79	    let descent = sqrt.height() - sqrt_ascent;
80	    let inner_ascent = sqrt_ascent + extra_ascender;
81	
82	    let mut sqrt_offset = Abs::zero();
83	    let mut shift_up = Abs::zero();
84	    let mut ascent = inner_ascent;
85	
86	    if let Some(index) = &index {
87	        sqrt_offset = kern_before + index.width() + kern_after;
88	        // The formula below for how much raise the index by comes from
89	        // the TeXbook, page 360, in the definition of `\root`.
90	        // However, the `+ index.descent()` part is different from TeX.
91	        // Without it, descenders can collide with the surd, a rarity
92	        // in practice, but possible.  MS Word also adjusts index positions
93	        // for descenders.
94	        shift_up = raise_factor * (inner_ascent - descent) + index.descent();
95	        ascent.set_max(shift_up + index.ascent());
96	    }
97	
98	    let sqrt_x = sqrt_offset.max(Abs::zero());
99	    let radicand_x = sqrt_x + sqrt.width();
100	    let radicand_y = ascent - radicand.ascent();
101	    let size = Size::new(radicand_x + line_width, ascent + descent);
102	
103	    // The extra "- thickness" comes from the fact that the sqrt is placed
104	    // in `push_frame` with respect to its top, not its baseline.
105	    let sqrt_pos = Point::new(sqrt_x, radicand_y - gap - thickness);
106	    let line_pos = Point::new(radicand_x, radicand_y - gap - (thickness / 2.0));
107	    let radicand_pos = Point::new(radicand_x, radicand_y);
108	
109	    let mut frame = Frame::soft(size);
110	    frame.set_baseline(ascent);
111	
112	    if let Some(index) = index {
113	        let index_x = -sqrt_offset.min(Abs::zero()) + kern_before;
114	        let index_pos = Point::new(index_x, ascent - index.ascent() - shift_up);
115	        frame.push_frame(index_pos, index);
116	    }
117	
118	    frame.push_frame(sqrt_pos, sqrt);
119	
120	    // Add the horizontal line of the root symbol.
121	    if let Some(fixed_stroke) = sqrt_stroke {
122	        let sides = styled_rect(
123	            Size::new(line_width, thickness),
124	            &Corners::splat(Rel::<Abs>::zero()),
125	            Some(text_fill),
126	            &Sides::new(
127	                None, // Omit the left-side edge.
128	                Some(fixed_stroke.clone()),
129	                Some(fixed_stroke.clone()),
130	                Some(fixed_stroke),
131	            ),
132	        );
133	        frame.push_multiple(sides.into_iter().map(|shape| {
134	            (
135	                line_pos - Point::with_y(thickness / 2.0),
136	                FrameItem::Shape(shape, props.span),
137	            )
138	        }));
139	    } else {
140	        let line = FrameItem::Shape(
141	            Geometry::Line(Point::with_x(line_width))
142	                .stroked(FixedStroke::from_pair(text_fill, thickness)),
143	            props.span,
144	        );
145	        frame.push(line_pos, line);
146	    }
147	
148	    frame.push_frame(radicand_pos, radicand);
149	
150	    ctx.push(FrameFragment::new(props, styles, frame));
151	    Ok(())
152	}
