24	/// Lays out a [`ScriptsItem`].
25	#[typst_macros::time(name = "math scripts layout", span = props.span)]
26	pub fn layout_scripts(
27	    item: &ScriptsItem,
28	    ctx: &mut MathContext,
29	    styles: StyleChain,
30	    props: &MathProperties,
31	) -> SourceResult<()> {
32	    macro_rules! layout {
33	        ($content:ident) => {
34	            item.$content
35	                .as_ref()
36	                .map(|script| ctx.layout_into_fragment(&script, styles))
37	                .transpose()?
38	        };
39	    }
40	
41	    // Layout the top and bottom attachments early so we can measure their
42	    // widths, in order to calculate what the stretch size is relative to.
43	    let t = layout!(top);
44	    let b = layout!(bottom);
45	    let relative_to_width = measure!(t, width).max(measure!(b, width));
46	    item.base.set_stretch_relative_to(relative_to_width, Axis::X);
47	
48	    let base = ctx.layout_into_fragment(&item.base, styles)?;
49	    let stretchy = base.is_stretchable(Axis::X);
50	
51	    let fragments = [
52	        layout!(top_left),
53	        t,
54	        layout!(top_right),
55	        layout!(bottom_left),
56	        b,
57	        layout!(bottom_right),
58	    ];
59	
60	    layout_attachments(
61	        ctx,
62	        props,
63	        item.base.styles().unwrap_or(styles),
64	        base,
65	        stretchy,
66	        fragments,
67	    )
68	}
