70	/// Lays out a [`PrimesItem`].
71	#[typst_macros::time(name = "math primes layout", span = props.span)]
72	pub fn layout_primes(
73	    item: &PrimesItem,
74	    ctx: &mut MathContext,
75	    styles: StyleChain,
76	    props: &MathProperties,
77	) -> SourceResult<()> {
78	    let Some(prime) =
79	        GlyphFragment::synthetic(ctx.engine, styles, PRIME_CHAR, props.span)
80	    else {
81	        return Ok(());
82	    };
83	    let prime = MathFragment::from(prime).into_frame();
84	    let width = prime.width() * (item.count + 1) as f64 / 2.0;
85	    let mut frame = Frame::soft(Size::new(width, prime.height()));
86	    frame.set_baseline(prime.ascent());
87	
88	    for i in 0..item.count {
89	        frame.push_frame(
90	            Point::new(prime.width() * (i as f64 / 2.0), Abs::zero()),
91	            prime.clone(),
92	        );
93	    }
94	
95	    ctx.push(FrameFragment::new(props, styles, frame).with_text_like(true));
96	    Ok(())
97	}
98	
99	/// Lay out the attachments.
100	fn layout_attachments(
101	    ctx: &mut MathContext,
102	    props: &MathProperties,
103	    styles: StyleChain,
104	    base: MathFragment,
105	    stretchy: bool,
106	    [tl, t, tr, bl, b, br]: [Option<MathFragment>; 6],
107	) -> SourceResult<()> {
108	    let (font, size) = base.font(ctx, styles);
109	    let cramped = styles.get(EquationElem::cramped);
110	
111	    // Calculate the distance from the base's baseline to the superscripts' and
112	    // subscripts' baseline.
113	    let (tx_shift, bx_shift) = if [&tl, &tr, &bl, &br].iter().all(|e| e.is_none()) {
114	        (Abs::zero(), Abs::zero())
115	    } else {
116	        compute_script_shifts(&font, size, cramped, &base, [&tl, &tr, &bl, &br])
117	    };
118	
119	    // Calculate the distance from the base's baseline to the top attachment's
120	    // and bottom attachment's baseline.
121	    let (t_shift, b_shift) =
122	        compute_limit_shifts(&font, size, &base, stretchy, [t.as_ref(), b.as_ref()]);
123	
124	    // Calculate the final frame height.
125	    let ascent = base
126	        .ascent()
127	        .max(tx_shift + measure!(tr, ascent))
128	        .max(tx_shift + measure!(tl, ascent))
129	        .max(t_shift + measure!(t, ascent));
130	    let descent = base
131	        .descent()
132	        .max(bx_shift + measure!(br, descent))
133	        .max(bx_shift + measure!(bl, descent))
134	        .max(b_shift + measure!(b, descent));
135	    let height = ascent + descent;
136	
137	    // Calculate the vertical position of each element in the final frame.
138	    let base_y = ascent - base.ascent();
139	    let tx_y = |tx: &MathFragment| ascent - tx_shift - tx.ascent();
140	    let bx_y = |bx: &MathFragment| ascent + bx_shift - bx.ascent();
141	    let t_y = |t: &MathFragment| ascent - t_shift - t.ascent();
142	    let b_y = |b: &MathFragment| ascent + b_shift - b.ascent();
143	
144	    // Calculate the distance each limit extends to the left and right of the
145	    // base's width.
146	    let ((t_pre_width, t_post_width), (b_pre_width, b_post_width)) =
147	        compute_limit_widths(&base, [t.as_ref(), b.as_ref()]);
148	
149	    // `space_after_script` is extra spacing that is at the start before each
150	    // pre-script, and at the end after each post-script (see the MathConstants
151	    // table in the OpenType MATH spec).
152	    let space_after_script = font.math().space_after_script.at(size);
153	
154	    // Calculate the distance each pre-script extends to the left of the base's
155	    // width.
156	    let (tl_pre_width, bl_pre_width) = compute_pre_script_widths(
157	        &base,
158	        [tl.as_ref(), bl.as_ref()],
159	        (tx_shift, bx_shift),
160	        space_after_script,
161	    );
162	
163	    // Calculate the distance each post-script extends to the right of the
164	    // base's width. Also calculate each post-script's kerning (we need this for
165	    // its position later).
166	    let ((tr_post_width, tr_kern), (br_post_width, br_kern)) = compute_post_script_widths(
167	        &base,
168	        [tr.as_ref(), br.as_ref()],
169	        (tx_shift, bx_shift),
170	        space_after_script,
171	    );
172	
173	    // Calculate the final frame width.
174	    let pre_width = t_pre_width.max(b_pre_width).max(tl_pre_width).max(bl_pre_width);
175	    let base_width = base.width();
176	    let post_width = t_post_width.max(b_post_width).max(tr_post_width).max(br_post_width);
177	    let width = pre_width + base_width + post_width;
178	
179	    // Calculate the horizontal position of each element in the final frame.
180	    let base_x = pre_width;
181	    let tl_x = pre_width - tl_pre_width + space_after_script;
182	    let bl_x = pre_width - bl_pre_width + space_after_script;
183	    let tr_x = pre_width + base_width + tr_kern;
184	    let br_x = pre_width + base_width + br_kern;
185	    let t_x = pre_width - t_pre_width;
186	    let b_x = pre_width - b_pre_width;
187	
188	    // Create the final frame.
189	    let mut frame = Frame::soft(Size::new(width, height));
190	    frame.set_baseline(ascent);
191	    frame.push_frame(Point::new(base_x, base_y), base.into_frame());
192	
193	    macro_rules! layout {
194	        ($e: ident, $x: ident, $y: ident) => {
195	            if let Some($e) = $e {
196	                frame.push_frame(Point::new($x, $y(&$e)), $e.into_frame());
197	            }
198	        };
199	    }
200	
201	    layout!(tl, tl_x, tx_y); // pre-superscript
202	    layout!(bl, bl_x, bx_y); // pre-subscript
203	    layout!(tr, tr_x, tx_y); // post-superscript
204	    layout!(br, br_x, bx_y); // post-subscript
205	    layout!(t, t_x, t_y); // upper-limit
206	    layout!(b, b_x, b_y); // lower-limit
207	
208	    // Done!
209	    ctx.push(FrameFragment::new(props, styles, frame));
210	    Ok(())
211	}
212	
213	/// Calculate the distance each post-script extends to the right of the base's
214	/// width, as well as its kerning value. Requires the distance from the base's
215	/// baseline to each post-script's baseline to obtain the correct kerning value.
216	/// Returns 2 tuples of two lengths, each first containing the distance the
217	/// post-script extends left of the base's width and second containing the
218	/// post-script's kerning value. The first tuple is for the post-superscript,
219	/// and the second is for the post-subscript.
220	fn compute_post_script_widths(
221	    base: &MathFragment,
222	    [tr, br]: [Option<&MathFragment>; 2],
223	    (tr_shift, br_shift): (Abs, Abs),
224	    space_after_post_script: Abs,
225	) -> ((Abs, Abs), (Abs, Abs)) {
226	    let tr_values = tr.map_or_default(|tr| {
227	        let kern = math_kern(base, tr, tr_shift, Corner::TopRight);
228	        (space_after_post_script + tr.width() + kern, kern)
229	    });
230	
231	    // The base's bounding box already accounts for its italic correction, so we
232	    // need to shift the post-subscript left by the base's italic correction
233	    // (see the kerning algorithm as described in the OpenType MATH spec).
234	    let br_values = br.map_or_default(|br| {
235	        let kern = math_kern(base, br, br_shift, Corner::BottomRight)
236	            - base.italics_correction();
237	        (space_after_post_script + br.width() + kern, kern)
238	    });
239	
240	    (tr_values, br_values)
241	}
242	
243	/// Calculate the distance each pre-script extends to the left of the base's
244	/// width. Requires the distance from the base's baseline to each pre-script's
245	/// baseline to obtain the correct kerning value.
246	/// Returns two lengths, the first being the distance the pre-superscript
247	/// extends left of the base's width and the second being the distance the
248	/// pre-subscript extends left of the base's width.
249	fn compute_pre_script_widths(
250	    base: &MathFragment,
251	    [tl, bl]: [Option<&MathFragment>; 2],
252	    (tl_shift, bl_shift): (Abs, Abs),
253	    space_before_pre_script: Abs,
254	) -> (Abs, Abs) {
255	    let tl_pre_width = tl.map_or_default(|tl| {
256	        let kern = math_kern(base, tl, tl_shift, Corner::TopLeft);
257	        space_before_pre_script + tl.width() + kern
258	    });
259	
260	    let bl_pre_width = bl.map_or_default(|bl| {
261	        let kern = math_kern(base, bl, bl_shift, Corner::BottomLeft);
262	        space_before_pre_script + bl.width() + kern
263	    });
264	
265	    (tl_pre_width, bl_pre_width)
266	}
267	
268	/// Calculate the distance each limit extends beyond the base's width, in each
269	/// direction. Can be a negative value if the limit does not extend beyond the
270	/// base's width, indicating how far into the base's width the limit extends.
271	/// Returns 2 tuples of two lengths, each first containing the distance the
272	/// limit extends leftward beyond the base's width and second containing the
273	/// distance the limit extends rightward beyond the base's width. The first
274	/// tuple is for the upper-limit, and the second is for the lower-limit.
275	fn compute_limit_widths(
276	    base: &MathFragment,
277	    [t, b]: [Option<&MathFragment>; 2],
278	) -> ((Abs, Abs), (Abs, Abs)) {
279	    // The upper- (lower-) limit is shifted to the right (left) of the base's
280	    // center by half the base's italic correction.
281	    let delta = base.italics_correction() / 2.0;
282	
283	    let t_widths = t.map_or_default(|t| {
284	        let half = (t.width() - base.width()) / 2.0;
285	        (half - delta, half + delta)
286	    });
287	
288	    let b_widths = b.map_or_default(|b| {
289	        let half = (b.width() - base.width()) / 2.0;
290	        (half + delta, half - delta)
291	    });
292	
293	    (t_widths, b_widths)
294	}
295	
296	/// Calculate the distance from the base's baseline to each limit's baseline.
297	/// Returns two lengths, the first being the distance to the upper-limit's
298	/// baseline and the second being the distance to the lower-limit's baseline.
299	fn compute_limit_shifts(
300	    font: &FontInstance,
301	    font_size: Abs,
302	    base: &MathFragment,
303	    stretchy: bool,
304	    [t, b]: [Option<&MathFragment>; 2],
305	) -> (Abs, Abs) {
306	    // `upper_gap_min` and `lower_gap_min` give gaps to the descender and
307	    // ascender of the limits respectively, whereas `upper_rise_min` and
308	    // `lower_drop_min` give gaps to each limit's baseline (see the
309	    // MathConstants table in the OpenType MATH spec).
310	    let t_shift = t.map_or_default(|t| {
311	        if stretchy {
312	            let top_shift_up = font.math().stretch_stack_top_shift_up.at(font_size);
313	            let gap_above_min = font.math().stretch_stack_gap_above_min.at(font_size);
314	            let gap = (top_shift_up - base.ascent() - t.descent()).max(gap_above_min);
315	            base.ascent() + gap + t.descent()
316	        } else {
317	            let upper_gap_min = font.math().upper_limit_gap_min.at(font_size);
318	            let upper_rise_min = font.math().upper_limit_baseline_rise_min.at(font_size);
319	            base.ascent() + upper_rise_min.max(upper_gap_min + t.descent())
320	        }
321	    });
322	
323	    let b_shift = b.map_or_default(|b| {
324	        if stretchy {
325	            let bottom_shift_down =
326	                font.math().stretch_stack_bottom_shift_down.at(font_size);
327	            let gap_below_min = font.math().stretch_stack_gap_below_min.at(font_size);
328	            let gap =
329	                (bottom_shift_down - base.descent() - b.ascent()).max(gap_below_min);
330	            base.descent() + gap + b.ascent()
331	        } else {
332	            let lower_gap_min = font.math().lower_limit_gap_min.at(font_size);
333	            let lower_drop_min = font.math().lower_limit_baseline_drop_min.at(font_size);
334	            base.descent() + lower_drop_min.max(lower_gap_min + b.ascent())
335	        }
336	    });
337	
338	    (t_shift, b_shift)
339	}
340	
341	/// Calculate the distance from the base's baseline to each script's baseline.
342	/// Returns two lengths, the first being the distance to the superscripts'
343	/// baseline and the second being the distance to the subscripts' baseline.
344	fn compute_script_shifts(
345	    font: &FontInstance,
346	    font_size: Abs,
347	    cramped: bool,
348	    base: &MathFragment,
349	    [tl, tr, bl, br]: [&Option<MathFragment>; 4],
350	) -> (Abs, Abs) {
351	    let sup_shift_up = (if cramped {
352	        font.math().superscript_shift_up_cramped
353	    } else {
354	        font.math().superscript_shift_up
355	    })
356	    .at(font_size);
357	
358	    let sup_bottom_min = font.math().superscript_bottom_min.at(font_size);
359	    let sup_bottom_max_with_sub =
360	        font.math().superscript_bottom_max_with_subscript.at(font_size);
361	    let sup_drop_max = font.math().superscript_baseline_drop_max.at(font_size);
362	    let gap_min = font.math().sub_superscript_gap_min.at(font_size);
363	    let sub_shift_down = font.math().subscript_shift_down.at(font_size);
364	    let sub_top_max = font.math().subscript_top_max.at(font_size);
365	    let sub_drop_min = font.math().subscript_baseline_drop_min.at(font_size);
366	
367	    let mut shift_up = Abs::zero();
368	    let mut shift_down = Abs::zero();
369	    let is_text_like = base.is_text_like();
370	
371	    if tl.is_some() || tr.is_some() {
372	        let ascent = base.base_ascent();
373	        shift_up = shift_up
374	            .max(sup_shift_up)
375	            .max(if is_text_like { Abs::zero() } else { ascent - sup_drop_max })
376	            .max(sup_bottom_min + measure!(tl, descent))
377	            .max(sup_bottom_min + measure!(tr, descent));
378	    }
379	
380	    if bl.is_some() || br.is_some() {
381	        let descent = base.base_descent();
382	        shift_down = shift_down
383	            .max(sub_shift_down)
384	            .max(if is_text_like { Abs::zero() } else { descent + sub_drop_min })
385	            .max(measure!(bl, ascent) - sub_top_max)
386	            .max(measure!(br, ascent) - sub_top_max);
387	    }
388	
389	    for (sup, sub) in [(tl, bl), (tr, br)] {
390	        if let (Some(sup), Some(sub)) = (&sup, &sub) {
391	            let sup_bottom = shift_up - sup.descent();
392	            let sub_top = sub.ascent() - shift_down;
393	            let gap = sup_bottom - sub_top;
394	            if gap >= gap_min {
395	                continue;
396	            }
397	
398	            let increase = gap_min - gap;
399	            let sup_only =
400	                (sup_bottom_max_with_sub - sup_bottom).clamp(Abs::zero(), increase);
401	            let rest = (increase - sup_only) / 2.0;
402	            shift_up += sup_only + rest;
403	            shift_down += rest;
404	        }
405	    }
406	
407	    (shift_up, shift_down)
408	}
409	
410	/// Calculate the kerning value for a script with respect to the base. A
411	/// positive value means shifting the script further away from the base, whereas
412	/// a negative value means shifting the script closer to the base. Requires the
413	/// distance from the base's baseline to the script's baseline, as well as the
414	/// script's corner (tl, tr, bl, br).
415	fn math_kern(base: &MathFragment, script: &MathFragment, shift: Abs, pos: Corner) -> Abs {
416	    // This process is described under the MathKernInfo table in the OpenType
417	    // MATH spec.
418	
419	    let (corr_height_top, corr_height_bot) = match pos {
420	        // Calculate two correction heights for superscripts:
421	        // - The distance from the superscript's baseline to the top of the
422	        //   base's bounding box.
423	        // - The distance from the base's baseline to the bottom of the
424	        //   superscript's bounding box.
425	        Corner::TopLeft | Corner::TopRight => {
426	            (base.ascent() - shift, shift - script.descent())
427	        }
428	        // Calculate two correction heights for subscripts:
429	        // - The distance from the base's baseline to the top of the
430	        //   subscript's bounding box.
431	        // - The distance from the subscript's baseline to the bottom of the
432	        //   base's bounding box.
433	        Corner::BottomLeft | Corner::BottomRight => {
434	            (script.ascent() - shift, shift - base.descent())
435	        }
436	    };
437	
438	    // Calculate the sum of kerning values for each correction height.
439	    let summed_kern = |height| {
440	        let base_kern = base.kern_at_height(pos, height);
441	        let attach_kern = script.kern_at_height(pos.inv(), height);
442	        base_kern + attach_kern
443	    };
444	
445	    // Take the smaller kerning amount (and so the larger value). Note that
446	    // there is a bug in the spec (as of 2024-08-15): it says to take the
447	    // minimum of the two sums, but as the kerning value is usually negative it
448	    // really means the smaller kern. The current wording of the spec could
449	    // result in glyphs colliding.
450	    summed_kern(corr_height_top).max(summed_kern(corr_height_bot))
451	}
