1	use typst_library::diag::SourceResult;
2	use typst_library::foundations::{Resolve, StyleChain};
3	use typst_library::layout::{
4	    Abs, AlignElem, Em, FixedAlignment, Frame, InlineItem, Point, Size,
5	};
6	use typst_library::math::ir::{AlignedRow, MathItem, MultilineItem};
7	use typst_library::math::{EquationElem, LeftRightAlternator, MathSize};
8	use typst_library::model::ParElem;
9	use unicode_math_class::MathClass;
10	
11	use super::MathContext;
12	use super::fragment::MathFragment;
13	
14	/// Leading between rows in script and scriptscript size.
15	const TIGHT_LEADING: Em = Em::new(0.25);
16	
17	/// A list of math fragments between alignment points and/or linebreaks.
18	///
19	/// For multiline equations this represents a distinct "cell", the list of
20	/// fragments at a specific row and column. For tables, this represents a
21	/// "sub-column", one of the parts that make up a cell in a table since
22	/// alignment points can be used to align fragments within a cell for an
23	/// individual column.
24	pub type MathRun = Vec<MathFragment>;
25	
26	/// Layout a [`MultilineItem`] into a [`MathRunFrameBuilder`].
27	pub fn layout_multiline(
28	    item: &MultilineItem,
29	    ctx: &mut MathContext,
30	    styles: StyleChain,
31	) -> SourceResult<MathRunFrameBuilder> {
32	    let nrows = item.rows.len();
33	    let ncols = item.rows.first().map_or(0, |r| r.len());
34	
35	    if nrows == 0 || ncols == 0 {
36	        return Ok(MathRunFrameBuilder::default());
37	    }
38	
39	    let mut col_widths = vec![Abs::zero(); ncols];
40	    let mut rows: Vec<Vec<MathRun>> = Vec::with_capacity(nrows);
41	    for row in &item.rows {
42	        let cells = layout_aligned_row(row, ctx, styles)?;
43	        for (c, cell) in cells.iter().enumerate() {
44	            col_widths[c].set_max(cell.iter().map(|f| f.width()).sum());
45	        }
46	        rows.push(cells);
47	    }
48	
49	    let leading = if styles.get(EquationElem::size) >= MathSize::Text {
50	        styles.resolve(ParElem::leading)
51	    } else {
52	        TIGHT_LEADING.resolve(styles)
53	    };
54	
55	    let align = styles.resolve(AlignElem::alignment).x;
56	    let rows = rows.into_iter().map(|cells| {
57	        let height = measure_row(&cells);
58	        RowLayout { cells, frame_height: height, row_height: None }
59	    });
60	
61	    Ok(stack_rows(
62	        rows,
63	        &col_widths,
64	        LeftRightAlternator::Right,
65	        align,
66	        leading,
67	        Abs::zero(),
68	    ))
69	}
70	
71	/// Layout an [`AlignedRow`].
72	pub fn layout_aligned_row(
73	    row: &AlignedRow,
74	    ctx: &mut MathContext,
75	    styles: StyleChain,
76	) -> SourceResult<Vec<MathRun>> {
77	    let mut cells = Vec::with_capacity(row.len());
78	    for (c, item) in row.iter().enumerate() {
79	        let mut frags = ctx.layout_into_fragments(item, styles)?;
80	
81	        // For a (right-aligned, left-aligned) pair, move the lspace of the item
82	        // in the left-aligned column to the right-aligned column.
83	        if c.is_multiple_of(2)
84	            && let Some(next_item) = row.get(c + 1)
85	            && let Some(spacing) = alignment_lspace(next_item)
86	        {
87	            frags.push(MathFragment::Space(spacing));
88	        }
89	
90	        cells.push(frags);
91	    }
92	
93	    Ok(cells)
94	}
95	
96	/// A single row to be laid out in multiline math.
97	pub struct RowLayout {
98	    /// The row's content, split by alignment points.
99	    pub cells: Vec<MathRun>,
100	    /// The ascent and descent that the row's final frame should have.
101	    pub frame_height: (Abs, Abs),
102	    /// The ascent and descent that should be used for this row when stacking
103	    /// rows together. If not specified,
104	    /// [`frame_height`](RowLayout::frame_height) is used instead.
105	    ///
106	    /// This is used in table layout, where within each column there are rows
107	    /// which need to be alignment. But when positioning rows together we need
108	    /// to align them based on the sizes of all columns of the table.
109	    pub row_height: Option<(Abs, Abs)>,
110	}
111	
112	/// Build and stack line frames for rows with aligned columns.
113	pub fn stack_rows(
114	    rows: impl IntoIterator<Item = RowLayout>,
115	    widths: &[Abs],
116	    alternator: LeftRightAlternator,
117	    align: FixedAlignment,
118	    leading: Abs,
119	    start_y: Abs,
120	) -> MathRunFrameBuilder {
121	    let (points, total_width) = cumulative_alignment_points(widths);
122	    let has_alignment = !points.is_empty();
123	
124	    let rows = rows.into_iter().map(|row| {
125	        let frame =
126	            row_into_line_frame(row.cells, &points, alternator, Some(row.frame_height));
127	        (frame, row.row_height.unwrap_or(row.frame_height))
128	    });
129	
130	    let mut frames = Vec::new();
131	    let mut size = Size::new(Abs::zero(), start_y);
132	
133	    for (i, (sub, (row_ascent, row_descent))) in rows.into_iter().enumerate() {
134	        if i > 0 {
