9	/// Lays out an [`AccentItem`].
10	#[typst_macros::time(name = "math accent layout", span = props.span)]
11	pub fn layout_accent(
12	    item: &AccentItem,
13	    ctx: &mut MathContext,
14	    styles: StyleChain,
15	    props: &MathProperties,
16	) -> SourceResult<()> {
17	    let top_accent = item.position == Position::Above;
18	
19	    let base = ctx.layout_into_fragment(&item.base, styles)?;
20	    let (font, size) = base.font(ctx, item.base.styles().unwrap_or(styles));
21	    let base_attach = base.accent_attach();
22	
23	    // Try to replace the accent glyph with its flattened variant.
24	    let flattened_base_height = font.math().flattened_accent_base_height.at(size);
25	    let accent = &item.accent;
26	    if top_accent && base.ascent() > flattened_base_height {
27	        accent.set_flac();
28	    }
29	
30	    accent.set_stretch_relative_to(base.width(), Axis::X);
31	    accent.set_stretch_font_size(size, Axis::X);
32	
33	    let accent = ctx.layout_into_fragment(accent, styles)?;
34	    let accent_attach = accent.accent_attach().0;
35	    let accent = accent.into_frame();
36	
37	    // Calculate the width of the final frame.
38	    let (width, base_x, accent_x) = {
39	        let base_attach = if top_accent { base_attach.0 } else { base_attach.1 };
40	        if !item.exact_frame_width {
41	            (base.width(), Abs::zero(), base_attach - accent_attach)
42	        } else {
43	            let pre_width = accent_attach - base_attach;
44	            let post_width =
45	                (accent.width() - accent_attach) - (base.width() - base_attach);
46	            let width =
47	                pre_width.max(Abs::zero()) + base.width() + post_width.max(Abs::zero());
48	            if pre_width < Abs::zero() {
49	                (width, Abs::zero(), -pre_width)
50	            } else {
51	                (width, pre_width, Abs::zero())
52	            }
53	        }
54	    };
55	
56	    let (gap, accent_pos, base_pos) = if top_accent {
57	        // Descent is negative because the accent's ink bottom is above the
58	        // baseline. Therefore, the default gap is the accent's negated descent
59	        // minus the accent base height. Only if the base is very small, we
60	        // need a larger gap so that the accent doesn't move too low.
61	        let accent_base_height = font.math().accent_base_height.at(size);
62	        let gap = -accent.descent() - base.ascent().min(accent_base_height);
63	        let accent_pos = Point::with_x(accent_x);
64	        let base_pos = Point::new(base_x, accent.height() + gap);
65	        (gap, accent_pos, base_pos)
66	    } else {
67	        let gap = -accent.ascent();
68	        let accent_pos = Point::new(accent_x, base.height() + gap);
69	        let base_pos = Point::with_x(base_x);
70	        (gap, accent_pos, base_pos)
71	    };
72	
73	    let size = Size::new(width, accent.height() + gap + base.height());
74	    let baseline = base_pos.y + base.ascent();
75	
