317	/// Resize the equation's frame accordingly so that it encompasses the number.
318	fn resize_equation(
319	    equation: &mut Frame,
320	    number: &Frame,
321	    number_align: Axes<FixedAlignment>,
322	    equation_align: FixedAlignment,
323	    width: Abs,
324	    is_multiline: bool,
325	    [first, last]: [(Axes<Abs>, Point, Abs); 2],
326	) -> Point {
327	    if matches!(number_align.y, FixedAlignment::Center if is_multiline) {
328	        // In this case, the center lines (not baselines) of the number frame
329	        // and the equation frame shall be aligned.
330	        return equation.resize(
331	            Size::new(width, equation.height().max(number.height())),
332	            Axes::<FixedAlignment>::new(equation_align, FixedAlignment::Center),
333	        );
334	    }
335	
336	    let excess_above = Abs::zero().max({
337	        if !is_multiline || matches!(number_align.y, FixedAlignment::Start) {
338	            let (.., baseline) = first;
339	            number.baseline() - baseline
340	        } else {
341	            Abs::zero()
342	        }
343	    });
344	    let excess_below = Abs::zero().max({
345	        if !is_multiline || matches!(number_align.y, FixedAlignment::End) {
346	            let (size, .., baseline) = last;
347	            (number.height() - number.baseline()) - (size.y - baseline)
348	        } else {
349	            Abs::zero()
350	        }
351	    });
352	
353	    // The vertical expansion is asymmetric on the top and bottom edges, so we
354	    // first align at the top then translate the content downward later.
355	    let resizing_offset = equation.resize(
356	        Size::new(width, equation.height() + excess_above + excess_below),
357	        Axes::<FixedAlignment>::new(equation_align, FixedAlignment::Start),
358	    );
359	    equation.translate(Point::with_y(excess_above));
360	    resizing_offset + Point::with_y(excess_above)
361	}
