1	use typst_library::diag::SourceResult;
2	use typst_library::foundations::{Resolve, StyleChain};
3	use typst_library::layout::{Abs, Em, Frame, FrameItem, Point, Rel, Size};
4	use typst_library::math::ir::{AlignedRow, MathProperties, TableItem};
5	use typst_library::math::{AugmentOffsets, style_for_denominator};
6	use typst_library::text::TextElem;
7	use typst_library::visualize::{FillRule, FixedStroke, Geometry, LineCap, Shape};
8	use typst_syntax::Span;
9	
10	use super::MathContext;
11	use super::fragment::{FrameFragment, GlyphFragment};
12	use super::run::{MathRun, RowLayout, layout_aligned_row, measure_row, stack_rows};
13	
14	const DEFAULT_STROKE_THICKNESS: Em = Em::new(0.05);
15	
16	/// Layout a [`TableItem`].
17	#[typst_macros::time(name = "math table layout", span = props.span)]
18	pub fn layout_table(
19	    item: &TableItem,
20	    ctx: &mut MathContext,
21	    styles: StyleChain,
22	    props: &MathProperties,
23	) -> SourceResult<()> {
24	    let rows = &item.cells;
25	    let nrows = rows.len();
26	    let ncols = rows.first().map_or(0, |row| row.len());
27	
28	    if ncols == 0 || nrows == 0 {
29	        ctx.push(FrameFragment::new(props, styles, Frame::soft(Size::zero())));
30	        return Ok(());
31	    }
32	
33	    let gap = item.gap.zip_map(ctx.region.size, Rel::relative_to);
34	    let half_gap = gap * 0.5;
35	
36	    // We provide a default stroke thickness that scales
37	    // with font size to ensure that augmentation lines
38	    // look correct by default at all matrix sizes.
39	    // The line cap is also set to square because it looks more "correct".
40	    let default_stroke_thickness = DEFAULT_STROKE_THICKNESS.resolve(styles);
41	    let default_stroke = FixedStroke {
42	        thickness: default_stroke_thickness,
43	        paint: styles.get_ref(TextElem::fill).as_decoration(),
44	        cap: LineCap::Square,
45	        ..Default::default()
46	    };
47	
48	    let (mut hline, mut vline, stroke) = match &item.augment {
49	        Some(augment) => {
50	            // We need to get stroke here for ownership.
51	            let stroke =
52	                augment.stroke.clone().unwrap_or_default().unwrap_or(default_stroke);
53	            (augment.hline.clone(), augment.vline.clone(), stroke)
54	        }
55	        _ => (AugmentOffsets::default(), AugmentOffsets::default(), default_stroke),
56	    };
57	
58	    // Before the full matrix body can be laid out, the
59	    // individual cells must first be independently laid out
60	    // so we can ensure alignment across rows and columns.
61	    let mut cols: Vec<Vec<CellLayout>> =
62	        (0..ncols).map(|_| Vec::with_capacity(nrows)).collect();
63	
64	    // This variable stores the maximum ascent and descent for each row.
65	    let mut heights = vec![(Abs::zero(), Abs::zero()); nrows];
66	
67	    let denom_style = style_for_denominator(styles);
68	    // We pad ascent and descent with the ascent and descent of the paren
69	    // to ensure that normal matrices are aligned with others unless they are
70	    // way too big.
71	    let (ascent, descent) = GlyphFragment::synthetic(
72	        ctx.engine,
73	        styles.chain(&denom_style),
74	        '(',
75	        Span::detached(),
76	    )
77	    .map(|glyph| (glyph.ascent(), glyph.descent()))
78	    .unwrap_or((Abs::zero(), Abs::zero()));
79	
80	    for (r, row) in rows.iter().enumerate() {
81	        for (c, cell) in row.iter().enumerate() {
82	            let cell = layout_cell(cell, ctx, styles)?;
83	
84	            heights[r].0.set_max(cell.height.0.max(ascent));
85	            heights[r].1.set_max(cell.height.1.max(descent));
86	
87	            cols[c].push(cell);
88	        }
89	    }
90	
91	    for line in &mut hline.0 {
92	        if *line < 0 {
93	            *line += nrows as isize;
94	        }
95	    }
96	
97	    for line in &mut vline.0 {
98	        if *line < 0 {
99	            *line += ncols as isize;
100	        }
101	    }
102	
103	    // For each row, combine maximum ascent and descent into a row height.
104	    // Sum the row heights, then add the total height of the gaps between rows.
105	    let mut total_height =
106	        heights.iter().map(|&(a, b)| a + b).sum::<Abs>() + gap.y * (nrows - 1) as f64;
107	
108	    if hline.0.contains(&0) {
109	        total_height += gap.y;
110	    }
111	
112	    if hline.0.contains(&(nrows as isize)) {
113	        total_height += gap.y;
114	    }
115	
116	    // Width starts at zero because it can't be calculated until later
117	    let mut frame = Frame::soft(Size::new(Abs::zero(), total_height));
118	
119	    let mut x = Abs::zero();
120	
121	    if vline.0.contains(&0) {
122	        frame.push(
123	            Point::with_x(x + half_gap.x),
124	            line_item(total_height, true, stroke.clone(), props.span),
125	        );
126	        x += gap.x;
127	    }
128	
129	    for (index, col) in cols.into_iter().enumerate() {
130	        let sub_widths = compute_sub_column_widths(&col);
131	        let rows = col.into_iter().enumerate().map(|(row, cell_layout)| RowLayout {
132	            cells: cell_layout.sub_columns,
133	            frame_height: cell_layout.height,
134	            row_height: Some(heights[row]),
135	        });
136	
137	        let builder = stack_rows(
138	            rows,
139	            &sub_widths,
140	            item.alternator,
141	            item.align,
142	            gap.y,
143	            if hline.0.contains(&0) { gap.y } else { Abs::zero() },
