47	    /// Creates a synthetic glyph fragment from the given character.
48	    pub fn synthetic(
49	        engine: &mut Engine,
50	        styles: StyleChain,
51	        c: char,
52	        span: Span,
53	    ) -> Option<Self> {
54	        let class = default_math_class(c).unwrap_or(MathClass::Normal);
55	        let math_size = styles.get(EquationElem::size);
56	        Self::base(
57	            engine.world,
58	            styles,
59	            &features(styles),
60	            c.encode_utf8(&mut [0; 4]),
61	            class,
62	            math_size,
63	        )
64	        .map(|glyph| glyph.with_span(span))
