67	    /// Creates a glyph fragment from the given text, stretching it if needed.
68	    pub fn new(
69	        engine: &mut Engine,
70	        text: &str,
71	        stretch: &Stretch,
72	        styles: StyleChain,
73	        props: &MathProperties,
74	        class: MathClass,
75	    ) -> Option<GlyphFragment> {
76	        let PlannedGlyph { mut glyph, action } =
77	            Self::planned(engine.world, styles, text, class, props.size, *stretch)?
78	                .with_span(props.span);
79	
80	        match action {
81	            Action::Stretch { axis, target, short_fall } => {
82	                glyph.stretch(engine, target, short_fall, axis);
83	                if axis == Axis::Y {
84	                    glyph.center_on_axis();
85	                }
86	            }
87	            Action::WarnBothAxes => {
88	                // As far as we know, there aren't any glyphs that have both
89	                // vertical and horizontal constructions. So for the time
90	                // being, we will assume that a glyph cannot have both.
91	                engine.sink.warn(warning!(
92	                   props.span,
93	                   "glyph has both vertical and horizontal constructions";
94	                   hint: "this is probably a font bug";
95	                   hint: "please file an issue at https://github.com/typst/typst/issues";
96	                ));
97	            }
98	            Action::Keep | Action::Fallback => {}
99	        }
100	
101	        Some(glyph)
102	    }
