104	    #[comemo::memoize]
105	    fn planned(
106	        world: Tracked<dyn World + '_>,
107	        styles: StyleChain,
108	        text: &str,
109	        class: MathClass,
110	        math_size: MathSize,
111	        stretch: Stretch,
112	    ) -> Option<PlannedGlyph> {
113	        let features = features(styles);
114	        let shape = |feats: &[rustybuzz::Feature]| {
115	            Self::base(world, styles, feats, text, class, math_size)
116	        };
117	
118	        let mut glyph = shape(&features)?;
119	        let mut action = decide(&glyph, &stretch);
120	
121	        // If the initial glyph isn't sufficient, keep retrying shaping, by
122	        // removing `ssty` and `flac` features, until one satisfies the stretch
123	        // requirements (or until we exhaust them all, in which case we keep
124	        // the original glyph, unstretched)
125	        if matches!(action, Action::Fallback) {
126	            shaping::feat_fallback(features, |feats| {
127	                let Some(new) = shape(feats) else { return false };
128	                match decide(&new, &stretch) {
129	                    Action::Fallback => false,
130	                    other => {
131	                        glyph = new;
132	                        action = other;
133	                        true
134	                    }
135	                }
136	            });
137	        }
138	
139	        Some(PlannedGlyph { glyph, action })
140	    }
