155	    /// Construct a glyph fragment from the shaped text.
156	    fn from_shaped(
157	        styles: StyleChain,
158	        text: EcoString,
159	        class: MathClass,
160	        math_size: MathSize,
161	        shaped: (FontInstance, Vec<Glyph>),
162	    ) -> GlyphFragment {
163	        let (font, glyphs) = shaped;
164	        let stretchable_axes = stretch_axes(&font, glyphs[0].id);
165	
166	        let item = TextItem {
167	            text,
168	            font,
169	            size: styles.resolve(TextElem::size),
170	            fill: styles.get_ref(TextElem::fill).as_decoration(),
171	            stroke: styles.resolve(TextElem::stroke).map(|s| s.unwrap_or_default()),
172	            lang: styles.get(TextElem::lang),
173	            region: styles.get(TextElem::region),
174	            glyphs,
175	        };
176	
177	        let mut fragment = Self {
178	            item,
179	            // Math
180	            math_size,
181	            class,
182	            stretchable_axes,
183	            // Math in need of updating.
184	            extended_shape: false,
185	            italics_correction: Abs::zero(),
186	            accent_attach: (Abs::zero(), Abs::zero()),
187	            size: Size::zero(),
188	            baseline: None,
189	            // Misc
190	            align: Abs::zero(),
