205	    /// Sets element id and boxes in appropriate way without changing other
206	    /// styles. This is used to replace the glyph with a stretch variant.
207	    fn update_glyph(&mut self) {
208	        let id = GlyphId(self.item.glyphs[0].id);
209	
210	        let extended_shape = is_extended_shape(&self.item.font, id);
211	        let italics = italics_correction(&self.item.font, id).unwrap_or_default();
212	        let width = self.item.width();
213	        if !extended_shape {
214	            self.item.glyphs[0].x_advance += italics;
215	        }
216	        let italics = italics.at(self.item.size);
217	
218	        let (ascent, descent) =
219	            ascent_descent(&self.item.font, id).unwrap_or((Em::zero(), Em::zero()));
220	
221	        // The fallback for accents is half the width plus or minus the italics
222	        // correction. This is similar to how top and bottom attachments are
223	        // shifted. For bottom accents we do not use the accent attach of the
224	        // base as it is meant for top acccents.
225	        let top_accent_attach = accent_attach(&self.item.font, id)
226	            .map(|x| x.at(self.item.size))
227	            .unwrap_or((width + italics) / 2.0);
228	        let bottom_accent_attach = (width - italics) / 2.0;
229	
230	        self.baseline = Some(ascent.at(self.item.size));
231	        self.size = Size::new(
232	            self.item.width(),
233	            ascent.at(self.item.size) + descent.at(self.item.size),
234	        );
235	        self.italics_correction = italics;
236	        self.accent_attach = (top_accent_attach, bottom_accent_attach);
237	        self.extended_shape = extended_shape;
238	    }
