254	    pub(super) fn into_frame(self) -> Frame {
255	        let mut frame = Frame::soft(self.size);
256	        frame.set_baseline(self.baseline());
257	        frame.push(
258	            Point::with_y(self.ascent() + self.shift + self.align),
259	            FrameItem::Text(self.item),
260	        );
261	        frame.modify(&self.modifiers);
262	        frame
263	    }
