265	    /// Try to stretch a glyph to a desired width or height.
266	    ///
267	    /// The resulting frame may not have the exact desired width or height.
268	    fn stretch(&mut self, engine: &mut Engine, target: Abs, short_fall: Abs, axis: Axis) {
269	        // If the base glyph is good enough, use it.
270	        let advance = self.stretch_advance(axis);
271	        let short_target = target - short_fall;
272	        if short_target <= advance {
273	            return;
274	        }
275	
276	        let id = GlyphId(self.item.glyphs[0].id);
277	        let font = self.item.font.clone();
278	        let Some(construction) = glyph_construction(&font, id, axis) else { return };
279	
280	        // Search for a pre-made variant with a good advance.
281	        let mut best_id = id;
282	        let mut best_advance = advance;
283	        for variant in construction.variants {
284	            best_id = variant.variant_glyph;
285	            best_advance =
286	                self.item.font.to_em(variant.advance_measurement).at(self.item.size);
287	            if short_target <= best_advance {
288	                break;
289	            }
290	        }
291	
292	        // This is either good or the best we've got.
293	        if short_target <= best_advance || construction.assembly.is_none() {
294	            self.item.glyphs = vec![Glyph {
295	                id: best_id.0,
296	                x_advance: self.item.font.x_advance(best_id.0).unwrap_or_default(),
297	                x_offset: Em::zero(),
298	                y_advance: self.item.font.y_advance(best_id.0).unwrap_or_default(),
299	                y_offset: Em::zero(),
300	                range: self.item.glyphs[0].range.clone(),
301	                span: self.item.glyphs[0].span,
302	            }];
303	            self.update_glyph();
304	            return;
305	        }
306	
307	        // Assemble from parts.
308	        let assembly = construction.assembly.unwrap();
309	        let min_overlap = min_connector_overlap(&self.item.font)
310	            .unwrap_or_default()
311	            .at(self.item.size);
312	        assemble(engine, self, assembly, min_overlap, target, axis);
313	    }
