362	/// How to proceed with the freshly-shaped glyph fragment.
363	#[derive(Clone, Copy)]
364	enum Action {
365	    /// Use this glyph as-is (no stretching is needed).
366	    Keep,
367	    /// Use this glyph and stretch it with the given information.
368	    Stretch { axis: Axis, target: Abs, short_fall: Abs },
369	    /// Use this glyph, but warn that it claims stretchability on both axes.
370	    WarnBothAxes,
371	    /// The glyph isn't stretchable on the axes we need and isn't wide enough
372	    /// to skip stretching (try falling back without some features).
373	    Fallback,
374	}
375	
376	/// Decide how to proceed with the freshly-shaped glyph fragment based on the
377	/// stretch required.
378	fn decide(glyph: &GlyphFragment, stretch: &Stretch) -> Action {
379	    /// The glyph's status for the stretch request on a single axis.
380	    enum AxisStatus {
381	        /// No stretching needed (none requested, or the glyph is already wide
382	        /// enough).
383	        Sufficient,
384	        /// The glyph is stretchable on this axis.
385	        Stretchable { target: Abs, short_fall: Abs },
386	        /// Stretching is needed but the glyph isn't stretchable and isn't wide
387	        /// enough (fallback and retry).
388	        Fallback,
389	    }
390	
391	    let font = &glyph.item.font;
392	    let id = glyph.item.glyphs[0].id;
393	    let axes = glyph.stretchable_axes;
394	
395	    let assess = |axis| {
396	        let Some((target, short_fall)) = resolve_stretch(glyph, stretch, axis) else {
397	            return AxisStatus::Sufficient;
398	        };
399	
400	        if axes.get(axis) {
401	            return AxisStatus::Stretchable { target, short_fall };
402	        }
403	        // Glyph isn't stretchable on this axis, but might be wide enough.
404	
405	        let mut advance = glyph.stretch_advance(axis);
406	
407	        // Combining marks (e.g. accent glyphs) typically have zero advance in
408	        // `hmtx`, so the advance above is no good. We explicitly compute the
409	        // bounding box, just in case.
410	        if let Some(bbox) = font.ttf().glyph_bounding_box(GlyphId(id)) {
411	            let extents = Axes::new(
412	                font.to_em(bbox.x_max - bbox.x_min),
413	                font.to_em(bbox.y_max - bbox.y_min),
414	            );
415	            advance.set_max(extents.get(axis).at(glyph.item.size));
416	        }
417	
418	        if target - short_fall <= advance {
419	            AxisStatus::Sufficient
420	        } else {
421	            AxisStatus::Fallback
422	        }
423	    };
424	
425	    match (assess(Axis::X), assess(Axis::Y)) {
426	        (AxisStatus::Stretchable { .. }, AxisStatus::Stretchable { .. }) => {
427	            Action::WarnBothAxes
428	        }
429	        (AxisStatus::Stretchable { target, short_fall }, _) => {
430	            Action::Stretch { axis: Axis::X, target, short_fall }
431	        }
432	        (_, AxisStatus::Stretchable { target, short_fall }) => {
433	            Action::Stretch { axis: Axis::Y, target, short_fall }
434	        }
435	        (AxisStatus::Sufficient, AxisStatus::Sufficient) => Action::Keep,
436	        _ => Action::Fallback,
437	    }
438	}
