440	/// Returns the absolute target and short fall of the stretch along the given
441	/// axis, if it exists.
442	fn resolve_stretch(
443	    glyph: &GlyphFragment,
444	    stretch: &Stretch,
445	    axis: Axis,
446	) -> Option<(Abs, Abs)> {
447	    let stretch = stretch.resolve(axis)?;
448	    let relative_to_size = stretch.relative_to.unwrap_or_else(|| {
449	        if axis == Axis::Y
450	            && glyph.class == MathClass::Large
451	            && glyph.math_size == MathSize::Display
452	        {
453	            glyph.item.font.math().display_operator_min_height.at(glyph.item.size)
454	        } else {
455	            glyph.size.get(axis)
456	        }
457	    });
458	
459	    let target = stretch.target.relative_to(relative_to_size);
460	    let short_fall = stretch.short_fall.at(stretch.font_size.unwrap_or(glyph.item.size));
461	    Some((target, short_fall))
462	}
