525	fn stretch_axes(font: &FontInstance, id: u16) -> Axes<bool> {
526	    let id = GlyphId(id);
527	    let horizontal = font
528	        .ttf()
529	        .tables()
530	        .math
531	        .and_then(|math| math.variants)
532	        .and_then(|variants| variants.horizontal_constructions.get(id))
533	        .is_some();
534	    let vertical = font
535	        .ttf()
536	        .tables()
537	        .math
538	        .and_then(|math| math.variants)
539	        .and_then(|variants| variants.vertical_constructions.get(id))
540	        .is_some();
541	
542	    Axes::new(horizontal, vertical)
543	}
