554	    font: &FontInstance,
555	    id: GlyphId,
556	    axis: Axis,
557	) -> Option<GlyphConstruction<'_>> {
558	    font.ttf()
559	        .tables()
560	        .math?
561	        .variants
562	        .map(|variants| match axis {
563	            Axis::X => variants.horizontal_constructions,
564	            Axis::Y => variants.vertical_constructions,
565	        })?
