569	/// Assemble a glyph from parts.
570	fn assemble(
571	    engine: &mut Engine,
572	    base: &mut GlyphFragment,
573	    assembly: GlyphAssembly,
574	    min_overlap: Abs,
575	    target: Abs,
576	    axis: Axis,
577	) {
578	    // Determine the number of times the extenders need to be repeated as well
579	    // as a ratio specifying how much to spread the parts apart
580	    // (0 = maximal overlap, 1 = minimal overlap).
581	    let mut full;
582	    let mut ratio;
583	    let mut repeat = 0;
584	    loop {
585	        full = Abs::zero();
586	        ratio = 0.0;
587	
588	        let mut parts = parts(assembly, repeat).peekable();
589	        let mut growable = Abs::zero();
590	
591	        while let Some(part) = parts.next() {
592	            let mut advance = base.item.font.to_em(part.full_advance).at(base.item.size);
593	            if let Some(next) = parts.peek() {
594	                let max_overlap = base
595	                    .item
596	                    .font
597	                    .to_em(part.end_connector_length.min(next.start_connector_length))
598	                    .at(base.item.size);
599	                if max_overlap < min_overlap {
600	                    // This condition happening is indicative of a bug in the
601	                    // font.
602	                    engine.sink.warn(warning!(
603	                       base.item.glyphs[0].span.0,
604	                       "glyph has assembly parts with overlap less than minConnectorOverlap";
605	                       hint: "its rendering may appear broken - this is probably a font bug";
606	                       hint: "please file an issue at https://github.com/typst/typst/issues";
607	                    ));
608	                }
609	
610	                advance -= max_overlap;
611	                // In case we have that max_overlap < min_overlap, ensure we
612	                // don't decrease the value of growable.
613	                growable += (max_overlap - min_overlap).max(Abs::zero());
614	            }
615	
616	            full += advance;
617	        }
618	
619	        if full < target {
620	            let delta = target - full;
621	            ratio = (delta / growable).min(1.0);
622	            full += ratio * growable;
623	        }
624	
625	        if target <= full || repeat >= MAX_REPEATS {
626	            break;
627	        }
628	
629	        repeat += 1;
630	    }
631	
632	    let mut glyphs = vec![];
633	    let mut parts = parts(assembly, repeat).peekable();
634	    while let Some(part) = parts.next() {
635	        let mut advance = base.item.font.to_em(part.full_advance).at(base.item.size);
636	        if let Some(next) = parts.peek() {
637	            let max_overlap = base
638	                .item
639	                .font
640	                .to_em(part.end_connector_length.min(next.start_connector_length))
641	                .at(base.item.size);
642	            advance -= max_overlap;
643	            advance += ratio * (max_overlap - min_overlap);
644	        }
645	        let (x_advance, y_advance, y_offset) = match axis {
646	            Axis::X => (Em::from_abs(advance, base.item.size), Em::zero(), Em::zero()),
647	            Axis::Y => (
648	                Em::zero(),
649	                Em::from_abs(advance, base.item.size),
650	                // Glyph parts used in vertical assemblies are typically aligned
651	                // at the vertical origin. This way, they combine properly when
652	                // drawn consecutively, as required by the MATH table spec.
653	                //
654	                // However, in some fonts, they aren't. To still have them align
655	                // properly, we are vertically offsetting such glyphs by their
656	                // bounding-box computed descent. (Positive descent means that
657	                // a glyph extends below the baseline and then we must move it
658	                // up for it to align properly. `y_advance` is Y-up, so that
659	                // matches up.)
660	                ascent_descent(&base.item.font, part.glyph_id)
661	                    .map(|x| x.1)
662	                    .unwrap_or_default(),
663	            ),
664	        };
665	        glyphs.push(Glyph {
666	            id: part.glyph_id.0,
667	            x_advance,
668	            x_offset: Em::zero(),
669	            y_advance,
670	            y_offset,
671	            range: base.item.glyphs[0].range.clone(),
672	            span: base.item.glyphs[0].span,
673	        });
674	    }
675	
676	    match axis {
677	        Axis::X => {
678	            base.size.x = full;
679	            let (ascent, descent) = glyphs
680	                .iter()
681	                .filter_map(|glyph| ascent_descent(&base.item.font, GlyphId(glyph.id)))
682	                .reduce(|(ma, md), (a, d)| (ma.max(a), md.max(d)))
683	                .unwrap_or((Em::zero(), Em::zero()));
684	            base.baseline = Some(ascent.at(base.item.size));
685	            base.size.y = (ascent + descent).at(base.item.size);
686	        }
687	        Axis::Y => {
688	            base.baseline = None;
689	            base.size.y = full;
690	            base.size.x = glyphs
691	                .iter()
692	                .map(|glyph| base.item.font.x_advance(glyph.id).unwrap_or_default())
693	                .max()
694	                .unwrap_or_default()
695	                .at(base.item.size);
696	        }
697	    }
698	
699	    base.item.glyphs = glyphs;
700	    base.italics_correction = base
701	        .item
702	        .font
703	        .to_em(assembly.italics_correction.value)
704	        .at(base.item.size);
705	    if axis == Axis::X {
706	        base.accent_attach = (full / 2.0, full / 2.0);
707	    }
708	    base.extended_shape = true;
709	}
710	
711	/// Return an iterator over the assembly's parts with extenders repeated the
712	/// specified number of times.
713	fn parts(
714	    assembly: GlyphAssembly<'_>,
715	    repeat: usize,
716	) -> impl Iterator<Item = GlyphPart> + '_ {
717	    assembly.parts.into_iter().flat_map(move |part| {
718	        let count = if part.part_flags.extender() { repeat } else { 1 };
719	        std::iter::repeat_n(part, count)
720	    })
721	}
